// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(address caller, address target, bytes calldata data, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(caller != c.Owner());
        vm.assume(target != address(c));
        vm.deal(caller, amount);
        bool ok;
        vm.prank(caller);
        try c.Command{value: amount}(target, data) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
